#include "ui/HubViewModel.h"
#include <windows.h>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>
using nh::Json;
static void Write(const std::filesystem::path& path,const Json& value){std::ofstream f(path,std::ios::binary);f<<value.dump();if(!f)throw std::runtime_error("receipt write");}
static Json Read(const std::filesystem::path& path){std::ifstream f(path);return Json::parse(f);}
static void Stop(nh::ProcessJob& job){if(job.process){if(WaitForSingleObject(job.process,0)!=WAIT_OBJECT_0){TerminateProcess(job.process,3);WaitForSingleObject(job.process,5000);}CloseHandle(job.process);job.process=nullptr;}job.busy=false;job.error.clear();}
static void Feed(nh::HubModel& m,const Json& receipt,bool closing=false){Stop(m.installer);Write(m.installer.result,receipt);wchar_t system[MAX_PATH];GetSystemDirectoryW(system,MAX_PATH);auto exe=std::filesystem::path(system)/L"cmd.exe";auto command=nh::Quote(exe.wstring())+L" /d /c exit 0";STARTUPINFOW s{sizeof(s)};PROCESS_INFORMATION p{};if(!CreateProcessW(exe.c_str(),command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&s,&p))throw std::runtime_error("inert child");CloseHandle(p.hThread);WaitForSingleObject(p.hProcess,5000);m.installer.process=p.hProcess;m.installer.busy=true;if(closing)m.PollClosing();else m.Poll();}
static nh::Game Game(const std::filesystem::path& root,const char* id){auto dir=root/id;std::filesystem::create_directories(dir);wchar_t system[MAX_PATH];GetSystemDirectoryW(system,MAX_PATH);auto exe=dir/L"Game.exe";std::filesystem::copy_file(std::filesystem::path(system)/L"cmd.exe",exe,std::filesystem::copy_options::overwrite_existing);nh::Game g;g.id=id;g.title=std::string(id)+" %s Ω & <Game>";g.store="Manual";g.root=nh::Utf8(dir.wstring());g.target.path=nh::Utf8(exe.wstring());g.target.bitness=64;g.target.suitable=true;return g;}
static void Begin(nh::HubModel& m){m.Plan("Install");auto request=Read(m.installer.request);Json p={{"status","Planned"},{"planId","fixture-plan"},{"planFingerprint","fixture-fingerprint"},{"request",request},{"target",{{"executable",request.at("gameExecutable")},{"directory",nh::Utf8(std::filesystem::path(nh::Wide(request.at("gameExecutable").get<std::string>())).parent_path().wstring())},{"fileIdentity","fixture-sha"}}},{"antiCheat",{{"scan_status","complete"},{"acknowledgementRequired",false},{"fingerprint","fixture-risk"}}}};Feed(m,p);if(!m.installer.busy||m.installer.readOnlyInstaller||m.installer.action!="Install")throw std::runtime_error("actual Execute not accepted: "+m.message);}
static Json Receipt(const nh::HubModel& m,std::string status="Succeeded"){return {{"status",status},{"planId","fixture-plan"},{"errors",Json::array()},{"skipped",Json::array()},{"inspection",{{"target",{{"executable",m.games[0].target.path}}},{"state",{{"status","Installed"},{"proxy","dxgi.dll"}}},{"settings",Json::array()}}}};}
template<class M> static std::string PendingTitle(const M& m){if constexpr(requires{m.installCompletion.Pending();}){if(auto p=m.installCompletion.Pending())return p->title;}return {};}
template<class M> static void Done(M& m){if constexpr(requires{m.installCompletion.Pending();}){if(auto p=m.installCompletion.Pending())m.installCompletion.Acknowledge(p->serial);}}
int main(){try{std::cout<<std::unitbuf;int checks=0,failed=0;auto check=[&](bool ok,const char* label){++checks;failed+=!ok;std::cout<<(ok?"PASS ":"FAIL ")<<label<<'\n';};auto root=nh::UserRoot()/L"completion-fixture";
 {nh::HubModel m;m.games={Game(root,"one"),Game(root,"two")};m.selected=0;Begin(m);const auto original=m.games[0].title;m.page=4;m.games[0].title="Later library title";m.Select(1);check(m.selected==0&&m.installer.busy,"existing mutating selection guard retained");check(PendingTitle(m).empty(),"no success while accepted write is busy");auto result=Receipt(m);Feed(m,result);check(PendingTitle(m)==original,"actual parsed full install receipt queues original immutable title on another page");m.selected=1;m.page=0;m.Poll();check(PendingTitle(m)==original,"pending completion survives page and selection changes");Done(m);m.Poll();check(PendingTitle(m).empty(),"Done consumes notice and polling cannot reopen it");Feed(m,result);check(PendingTitle(m).empty(),"repeated receipt without accepted operation cannot recreate notice");Stop(m.installer);}
 for(const char* status:{"Partial","Failed","FailedWithoutChanges","Cancelled","Inspected","DefaultsResolved","RecoveryRequired"}){nh::HubModel m;m.games={Game(root,"one")};m.selected=0;Begin(m);Feed(m,Receipt(m,status));check(PendingTitle(m).empty(),status);Stop(m.installer);}
 for(int variant=0;variant<5;++variant){nh::HubModel m;m.games={Game(root,"one"),Game(root,"two")};m.selected=0;Begin(m);auto result=Receipt(m,"SucceededWithNotes");if(variant==0)result["planId"]="different-plan";if(variant==1)result["inspection"]["target"]["executable"]=m.games[1].target.path;if(variant==2)result["inspection"]["state"]["status"]="Partial";if(variant==3)result["errors"]=Json::array({"unresolved error"});if(variant==4)result["skipped"]=Json::array({"skipped.dll"});Feed(m,result);check(PendingTitle(m).empty(),"partial/mismatched/noteful incomplete receipt cannot claim completion");Stop(m.installer);}
 {nh::HubModel m;m.games={Game(root,"one")};m.selected=0;Begin(m);auto original=m.games[0].title;Feed(m,Receipt(m,"SucceededWithNotes"));check(PendingTitle(m)==original,"full install with informational notes is complete");Done(m);check(PendingTitle(m).empty(),"acknowledgment clears exactly pending completion");Stop(m.installer);}
 {nh::HubModel m;m.games={Game(root,"one")};m.selected=0;Begin(m);Feed(m,Receipt(m),true);check(!m.installer.busy,"closing drains real child without altering write ownership");Stop(m.installer);}
 std::cout<<"RESULT checks="<<checks<<" failures="<<failed<<" actualHubModel=true actualProcessJobReceiptParse=true helper=idle_fixture no_game_operations=true\n";return failed?1:0;}catch(const std::exception& e){std::cerr<<"SETUP_OR_RUNTIME_ERROR "<<e.what()<<'\n';return 2;}}
